# Hindi / Gujarati text for History Ch 4 lesson, sections 4-6.
TEXT_B = {
 "s4.thm.title": ("भारतीय वस्त्रों का युग", "ભારતીય કાપડનો યુગ"),
 "s4.thm.body": (
  "मशीन उद्योगों के युग से पहले **अंतरराष्ट्रीय वस्त्र बाज़ार में भारत के रेशमी और सूती माल का दबदबा** था। मोटा कपास कई देशों में बनता था, पर **महीन किस्म** का कपड़ा भारत से आता था।\n\n"
  "- **आर्मीनियाई और फ़ारसी सौदागर** पंजाब से अफ़ग़ानिस्तान, पूर्वी फ़ारस और मध्य एशिया तक माल ले जाते थे।\n- उपनिवेश-पूर्व बंदरगाह: गुजरात के तट पर **सूरत** भारत को खाड़ी और लाल सागर के बंदरगाहों से जोड़ता था; कोरोमंडल तट पर **मछलीपट्टनम** और बंगाल में **हुगली** का दक्षिण-पूर्व एशियाई बंदरगाहों से व्यापार था।\n"
  "- भारतीय सौदागर और बैंकर उत्पादन के लिए पैसा देते, माल ढोते और निर्यातकों को आपूर्ति करते थे; आपूर्ति सौदागर बंदरगाहों को भीतरी क्षेत्रों से जोड़ते थे।\n\n"
  "**टूटन:** **1750 के दशक** तक यूरोपीय कंपनियों की ताक़त बढ़ने से यह जाल टूटने लगा, क्योंकि उन्हें स्थानीय रियायतें और एकाधिकार मिल रहे थे। **सूरत और हुगली का पतन** हुआ; वहाँ से निर्यात बहुत घट गया, क़र्ज़ मिलना बंद हो गया और स्थानीय बैंकर दिवालिया हो गए। "
  "17वीं सदी के अंतिम वर्षों में सूरत से होने वाले व्यापार का कुल मूल्य **1.6 करोड़ रुपये** था; 1740 के दशक तक यह बहुत गिर गया। नए बंदरगाह, **बंबई और कलकत्ता**, औपनिवेशिक सत्ता के अधीन बढ़े, और व्यापार यूरोपीय कंपनियों और यूरोपीय जहाज़ों के हाथ में चला गया।",
  "યંત્ર ઉદ્યોગોના યુગ પહેલાં **આંતરરાષ્ટ્રીય કાપડ બજારમાં ભારતના રેશમી અને સુતરાઉ માલનું વર્ચસ્વ** હતું. જાડું કાપડ અનેક દેશોમાં બનતું, પણ **બારીક જાતનું** કાપડ ભારતથી આવતું.\n\n"
  "- **આર્મેનિયન અને ઈરાની વેપારીઓ** પંજાબથી અફઘાનિસ્તાન, પૂર્વ ઈરાન અને મધ્ય એશિયા સુધી માલ લઈ જતા.\n- સંસ્થાનકાળ પહેલાંનાં બંદરો: ગુજરાતના કાંઠે **સુરત** ભારતને અખાત અને રાતા સમુદ્રનાં બંદરો સાથે જોડતું; કોરોમંડલ કાંઠે **મછલીપટ્ટનમ** અને બંગાળમાં **હુગલી**નો અગ્નિ એશિયાનાં બંદરો સાથે વેપાર હતો.\n"
  "- ભારતીય વેપારીઓ અને શરાફો ઉત્પાદન માટે નાણાં આપતા, માલ લઈ જતા અને નિકાસકારોને પુરવઠો આપતા; પુરવઠા વેપારીઓ બંદરોને અંદરના પ્રદેશો સાથે જોડતા.\n\n"
  "**ભંગાણ:** **1750ના દાયકા** સુધીમાં યુરોપીય કંપનીઓની તાકાત વધતાં આ જાળું તૂટવા લાગ્યું, કારણ કે તેમને સ્થાનિક છૂટછાટો અને ઇજારા મળતા હતા. **સુરત અને હુગલીનું પતન** થયું; ત્યાંથી નિકાસ ખૂબ ઘટી, ધિરાણ મળવું બંધ થયું અને સ્થાનિક શરાફો નાદાર થયા. "
  "17મી સદીનાં છેલ્લાં વર્ષોમાં સુરત મારફતે થતા વેપારનું કુલ મૂલ્ય **₹1.6 કરોડ** હતું; 1740ના દાયકા સુધીમાં તે ઘણું ઘટ્યું. નવાં બંદરો, **મુંબઈ અને કલકત્તા**, સંસ્થાનવાદી સત્તા હેઠળ વિકસ્યાં, અને વેપાર યુરોપીય કંપનીઓ અને યુરોપીય જહાજોના હાથમાં ગયો."),
 "s4.weavers.title": ("बुनकरों का क्या हुआ?", "વણકરોનું શું થયું?"),
 "s4.weavers.body": (
  "1760 और 1770 के दशक में बंगाल और कर्नाटक में राजनीतिक सत्ता स्थापित करने के बाद ईस्ट इंडिया कंपनी ने **प्रतिस्पर्धा ख़त्म करने, लागत पर नियंत्रण रखने और सूती तथा रेशमी माल की नियमित आपूर्ति** सुनिश्चित करने की कोशिश की:\n\n"
  "- कपड़ा व्यापार से जुड़े मौजूदा व्यापारियों और दलालों को हटाकर बुनकरों पर सीधा नियंत्रण बनाने की कोशिश की।\n"
  "- बुनकरों पर निगरानी रखने, माल इकट्ठा करने और कपड़े की गुणवत्ता जाँचने के लिए **गुमाश्ता** नामक वेतनभोगी कर्मचारी नियुक्त किए।\n"
  "- **पेशगी की व्यवस्था** से कंपनी के बुनकरों को दूसरे ख़रीदारों से सौदा करने से रोका: ऑर्डर मिलते ही बुनकरों को कच्चा माल ख़रीदने के लिए क़र्ज़ दिया जाता, और क़र्ज़ लेने वालों को अपना कपड़ा गुमाश्ता को ही सौंपना पड़ता।\n\n"
  "गुमाश्ते बाहरी लोग थे जिनका गाँव से कोई पुराना सामाजिक संबंध नहीं था। वे घमंड से पेश आते, सिपाहियों और चपरासियों के साथ गाँवों में आते, और देरी के लिए बुनकरों को सज़ा देते, अक्सर पीटते और कोड़े लगाते। बुनकरों के लिए क़ीमत पर मोलभाव की गुंजाइश ख़त्म हो गई, और कंपनी से मिलने वाली क़ीमत बहुत कम थी। "
  "कर्नाटक और बंगाल में कई जगह बुनकर **गाँव छोड़कर** चले गए, कुछ ने गाँव के व्यापारियों के साथ मिलकर **विद्रोह** किया, और कई ने क़र्ज़ लेने से मना कर दिया, अपनी कार्यशालाएँ बंद कर दीं और **खेतिहर मज़दूर** बन गए।",
  "1760 અને 1770ના દાયકામાં બંગાળ અને કર્ણાટકમાં રાજકીય સત્તા સ્થાપ્યા પછી ઈસ્ટ ઇન્ડિયા કંપનીએ **સ્પર્ધા નાબૂદ કરવા, ખર્ચ પર નિયંત્રણ રાખવા અને સુતરાઉ તથા રેશમી માલનો નિયમિત પુરવઠો** સુનિશ્ચિત કરવા પ્રયત્ન કર્યો:\n\n"
  "- કાપડના વેપાર સાથે જોડાયેલા હાલના વેપારીઓ અને દલાલોને દૂર કરીને વણકરો પર સીધું નિયંત્રણ સ્થાપવાનો પ્રયત્ન કર્યો.\n"
  "- વણકરો પર દેખરેખ રાખવા, માલ એકઠો કરવા અને કાપડની ગુણવત્તા તપાસવા **ગુમાસ્તા** નામના પગારદાર નોકરો નીમ્યા.\n"
  "- **પેશગી (અગાઉથી ધિરાણ)ની વ્યવસ્થા**થી કંપનીના વણકરોને બીજા ખરીદદારો સાથે સોદો કરતાં રોક્યા: ઑર્ડર મળતાં જ વણકરોને કાચો માલ ખરીદવા લોન અપાતી, અને લોન લેનારાઓને પોતાનું કાપડ ગુમાસ્તાને જ સોંપવું પડતું.\n\n"
  "ગુમાસ્તાઓ બહારના લોકો હતા જેમનો ગામ સાથે કોઈ જૂનો સામાજિક સંબંધ ન હતો. તેઓ ઘમંડથી વર્તતા, સિપાઈઓ અને પટાવાળા સાથે ગામમાં આવતા, અને મોડું થાય તો વણકરોને સજા કરતા, ઘણી વાર માર મારતા અને કોરડા ફટકારતા. વણકરો પાસે ભાવતાલ કરવાની જગ્યા ન રહી, અને કંપની પાસેથી મળતો ભાવ ખૂબ ઓછો હતો. "
  "કર્ણાટક અને બંગાળમાં ઘણી જગ્યાએ વણકરો **ગામ છોડીને** ગયા, કેટલાકે ગામના વેપારીઓ સાથે મળીને **બળવો** કર્યો, અને ઘણાએ લોન લેવાની ના પાડી, પોતાની કાર્યશાળાઓ બંધ કરી અને **ખેતમજૂર** બન્યા."),
 "s4.table.title": ("बुनकरों पर कंपनी का नियंत्रण", "વણકરો પર કંપનીનું નિયંત્રણ"),
 "s4.table.body": (
  "| कंपनी का क़दम | बुनकरों पर असर |\n|---|---|\n| मौजूदा व्यापारियों और दलालों को हटाया | बुनकरों के पुराने संपर्क टूट गए |\n| बुनकरों की निगरानी, माल इकट्ठा करने और गुणवत्ता जाँचने के लिए **गुमाश्ते** (वेतनभोगी कर्मचारी) नियुक्त किए | बाहरी लोग जो घमंड से पेश आते; देरी पर बुनकरों को अक्सर पीटा और कोड़े लगाए जाते |\n"
  "| **पेशगी की व्यवस्था**: कच्चे माल के लिए क़र्ज़, कपड़ा गुमाश्ता को सौंपना | बुनकर दूसरे ख़रीदारों को नहीं बेच सकते थे और न मोलभाव कर सकते थे; बहुत कम क़ीमत मिलती थी |\n"
  "| परिणाम | कई बुनकरों ने गाँव छोड़े, विद्रोह किया, क़र्ज़ लेने से मना किया या खेतिहर मज़दूर बन गए |",
  "| કંપનીનું પગલું | વણકરો પર અસર |\n|---|---|\n| હાલના વેપારીઓ અને દલાલોને દૂર કર્યા | વણકરોના જૂના સંપર્કો તૂટ્યા |\n| વણકરોની દેખરેખ, માલ એકઠો કરવા અને ગુણવત્તા તપાસવા **ગુમાસ્તા** (પગારદાર નોકરો) નીમ્યા | બહારના લોકો જે ઘમંડથી વર્તતા; મોડું થાય તો વણકરોને ઘણી વાર માર અને કોરડા પડતા |\n"
  "| **પેશગીની વ્યવસ્થા**: કાચા માલ માટે લોન, કાપડ ગુમાસ્તાને સોંપવું | વણકરો બીજા ખરીદદારોને વેચી શકતા ન હતા કે ભાવતાલ કરી શકતા ન હતા; ખૂબ ઓછો ભાવ મળતો |\n"
  "| પરિણામ | ઘણા વણકરોએ ગામ છોડ્યાં, બળવો કર્યો, લોન લેવાની ના પાડી કે ખેતમજૂર બન્યા |"),
 "s4.manchester.title": ("मैनचेस्टर भारत आता है", "માન્ચેસ્ટર ભારત આવે છે"),
 "s4.manchester.body": (
  "**1772** में कंपनी के अधिकारी हेनरी पतुलो ने कहा कि भारतीय वस्त्रों की माँग कभी कम नहीं हो सकती। फिर भी 19वीं सदी की शुरुआत से भारतीय वस्त्र-निर्यात में लंबी गिरावट शुरू हुई: **1811–12** में भारत के निर्यात में सूती कपड़े का हिस्सा **33 प्रतिशत** था; **1850–51** तक यह **3 प्रतिशत** से अधिक नहीं रहा।\n\n"
  "- **मैनचेस्टर** के उद्योगपतियों ने सरकार पर दबाव डाला कि ब्रिटेन में सूती कपड़ों के आयात पर शुल्क लगाया जाए, ताकि वहाँ उनके माल से कोई प्रतिस्पर्धा न हो, और कंपनी को भारतीय बाज़ारों में ब्रिटिश माल बेचने के लिए राज़ी किया।\n"
  "- 18वीं सदी के अंत में भारत में सूती कपड़े का लगभग कोई आयात नहीं था; **1850** तक भारत के आयात के मूल्य में सूती कपड़े का हिस्सा **31 प्रतिशत** से अधिक और **1870 के दशक** तक **50 प्रतिशत** से अधिक हो गया।\n\n"
  "**बुनकरों के सामने दो समस्याएँ थीं:** उनका **निर्यात बाज़ार ढह गया** और **स्थानीय बाज़ार सिकुड़ गया**, जो मैनचेस्टर के सस्ते मशीनी माल से भर गया। और उन्हें अच्छा **कच्चा कपास** नहीं मिलता था: **1860 के दशक** में **अमेरिकी गृहयुद्ध** छिड़ने और अमेरिका से कपास की आपूर्ति कटने पर ब्रिटेन भारत की ओर मुड़ा। भारत से कच्चे कपास का निर्यात बढ़ा, क़ीमतें आसमान छूने लगीं, और भारतीय बुनकरों को कच्चा कपास नहीं मिला या मनमानी क़ीमत पर ख़रीदना पड़ा। "
  "19वीं सदी के अंत तक भारत में भी कारख़ानों ने उत्पादन शुरू कर दिया और बाज़ार मशीनी माल से भर गया।",
  "**1772**માં કંપનીના અધિકારી હેન્રી પટુલોએ કહ્યું કે ભારતીય કાપડની માગ ક્યારેય ઘટી શકે નહિ. છતાં 19મી સદીની શરૂઆતથી ભારતીય કાપડની નિકાસમાં લાંબો ઘટાડો શરૂ થયો: **1811–12**માં ભારતની નિકાસમાં સુતરાઉ કાપડનો હિસ્સો **33 ટકા** હતો; **1850–51** સુધીમાં તે **3 ટકા**થી વધુ ન રહ્યો.\n\n"
  "- **માન્ચેસ્ટર**ના ઉદ્યોગપતિઓએ સરકાર પર દબાણ કર્યું કે બ્રિટનમાં સુતરાઉ કાપડની આયાત પર જકાત નાખવામાં આવે, જેથી ત્યાં તેમના માલને કોઈ સ્પર્ધા ન રહે, અને કંપનીને ભારતીય બજારોમાં બ્રિટિશ માલ વેચવા મનાવી.\n"
  "- 18મી સદીના અંતે ભારતમાં સુતરાઉ કાપડની લગભગ કોઈ આયાત ન હતી; **1850** સુધીમાં ભારતની આયાતના મૂલ્યમાં સુતરાઉ કાપડનો હિસ્સો **31 ટકા**થી વધુ અને **1870ના દાયકા** સુધીમાં **50 ટકા**થી વધુ થયો.\n\n"
  "**વણકરો સામે બે સમસ્યાઓ હતી:** તેમનું **નિકાસ બજાર તૂટી પડ્યું** અને **સ્થાનિક બજાર સંકોચાયું**, જે માન્ચેસ્ટરના સસ્તા યંત્રનિર્મિત માલથી ભરાઈ ગયું. અને તેમને સારો **કાચો કપાસ** મળતો ન હતો: **1860ના દાયકામાં** **અમેરિકન આંતરવિગ્રહ** ફાટી નીકળ્યો અને અમેરિકાથી કપાસનો પુરવઠો કપાયો ત્યારે બ્રિટન ભારત તરફ વળ્યું. ભારતમાંથી કાચા કપાસની નિકાસ વધી, ભાવ આસમાને પહોંચ્યા, અને ભારતીય વણકરોને કાચો કપાસ ન મળ્યો કે મનફાવતા ભાવે ખરીદવો પડ્યો. "
  "19મી સદીના અંત સુધીમાં ભારતમાં પણ કારખાનાંએ ઉત્પાદન શરૂ કર્યું અને બજાર યંત્રનિર્મિત માલથી ભરાઈ ગયું."),

 "s5.thm.title": ("पहली मिलें और पहले उद्यमी", "પહેલી મિલો અને પહેલા ઉદ્યોગસાહસિકો"),
 "s5.thm.body": (
  "- **बंबई की पहली सूती मिल** **1854** में बनी और दो साल बाद उसमें उत्पादन शुरू हुआ। 1862 तक चार मिलें 94,000 तकुओं और 2,150 करघों के साथ चल रही थीं।\n"
  "- **बंगाल की पहली जूट मिल** **1855** में और दूसरी 1862 में बनी। उत्तर भारत में **कानपुर** में 1860 के दशक में **एल्गिन मिल** शुरू हुई, और एक साल बाद **अहमदाबाद की पहली सूती मिल** बनी। **1874** तक **मद्रास** की पहली कताई और बुनाई मिल में उत्पादन शुरू हो गया।\n\n"
  "**आरंभिक उद्यमियों** ने व्यापार, विशेषकर चीन के साथ व्यापार से पैसा कमाया था:\n- **द्वारकानाथ टैगोर** ने चीन व्यापार से धन कमाया और 1830 और 1840 के दशक में **छह संयुक्त उद्यम कंपनियाँ** बनाईं।\n"
  "- बंबई में **डिनशॉ पेटिट और जमशेदजी नुसरवानजी टाटा जैसे पारसियों** ने विशाल औद्योगिक साम्राज्य खड़े किए; उनकी दौलत का एक हिस्सा चीन को निर्यात से और एक हिस्सा इंग्लैंड को कच्चे कपास की आपूर्ति से आया।\n"
  "- **1917 में कलकत्ता में देश की पहली जूट मिल** लगाने वाले मारवाड़ी व्यवसायी **सेठ हुकुमचंद** ने भी चीन से व्यापार किया था, और उद्योगपति **जी. डी. बिड़ला** के पिता और दादा ने भी।\n"
  "- औपनिवेशिक नियंत्रण कसने पर भारतीय व्यवसायियों को कई वस्तुओं के व्यापार से रोका गया। प्रथम विश्व युद्ध तक **यूरोपीय प्रबंधकीय एजेंसियाँ** (जैसे बर्ड हीगलर्स एंड कंपनी, एंड्रयू यूल और जार्डीन स्किनर एंड कंपनी) भारतीय उद्योग के बड़े हिस्से पर नियंत्रण रखती थीं।\n\n"
  "**मज़दूर कहाँ से आए?** अधिकतर आसपास के ज़िलों से। **1911** में बंबई के सूती कपड़ा उद्योग के आधे मज़दूर पास के **रत्नागिरी** ज़िले से थे; कानपुर की मिलों को अधिकतर मज़दूर कानपुर ज़िले के गाँवों से मिलते थे। "
  "नौकरी पाना कठिन था; उद्योगपति नए मज़दूरों की भर्ती के लिए **जॉबर** रखते थे, जो प्रायः पुराना और भरोसेमंद मज़दूर होता था; वह अपने गाँव से लोगों को लाता, उन्हें बसाने में मदद करता और मुसीबत में पैसा देता था। समय के साथ जॉबर पैसे और तोहफ़े माँगने लगे और मज़दूरों की ज़िंदगी पर नियंत्रण रखने लगे। "
  "कारख़ाना मज़दूरों की संख्या **1901 में 5,84,000** से बढ़कर **1946 तक 24,36,000** से अधिक हो गई।",
  "- **મુંબઈની પહેલી સુતરાઉ મિલ** **1854**માં બની અને બે વર્ષ પછી તેમાં ઉત્પાદન શરૂ થયું. 1862 સુધીમાં ચાર મિલો 94,000 ત્રાક અને 2,150 શાળો સાથે ચાલતી હતી.\n"
  "- **બંગાળની પહેલી શણ મિલ** **1855**માં અને બીજી 1862માં બની. ઉત્તર ભારતમાં **કાનપુર**માં 1860ના દાયકામાં **એલ્ગિન મિલ** શરૂ થઈ, અને એક વર્ષ પછી **અમદાવાદની પહેલી સુતરાઉ મિલ** સ્થપાઈ. **1874** સુધીમાં **મદ્રાસ**ની પહેલી કાંતણ અને વણાટ મિલમાં ઉત્પાદન શરૂ થયું.\n\n"
  "**શરૂઆતના ઉદ્યોગસાહસિકોએ** વેપાર, ખાસ કરીને ચીન સાથેના વેપારથી નાણાં કમાયાં હતાં:\n- **દ્વારકાનાથ ટાગોરે** ચીનના વેપારમાંથી ધન કમાયું અને 1830 અને 1840ના દાયકામાં **છ સંયુક્ત મૂડી કંપનીઓ** સ્થાપી.\n"
  "- મુંબઈમાં **દિનશા પેટિટ અને જમશેદજી નસરવાનજી તાતા જેવા પારસીઓએ** વિશાળ ઔદ્યોગિક સામ્રાજ્યો ઊભાં કર્યાં; તેમની સંપત્તિનો એક ભાગ ચીનમાં નિકાસથી અને એક ભાગ ઇંગ્લૅન્ડને કાચા કપાસના પુરવઠાથી આવ્યો.\n"
  "- **1917માં કલકત્તામાં દેશની પહેલી શણ મિલ** સ્થાપનાર મારવાડી વેપારી **શેઠ હુકમચંદે** પણ ચીન સાથે વેપાર કર્યો હતો, અને ઉદ્યોગપતિ **જી. ડી. બિરલા**ના પિતા અને દાદાએ પણ.\n"
  "- સંસ્થાનવાદી નિયંત્રણ કડક થતાં ભારતીય વેપારીઓને ઘણી વસ્તુઓના વેપારથી રોકાયા. પ્રથમ વિશ્વયુદ્ધ સુધી **યુરોપીય મૅનેજિંગ એજન્સીઓ** (જેમ કે બર્ડ હીગલર્સ ઍન્ડ કંપની, ઍન્ડ્રુ યૂલ અને જાર્ડિન સ્કિનર ઍન્ડ કંપની) ભારતીય ઉદ્યોગના મોટા ભાગ પર નિયંત્રણ રાખતી.\n\n"
  "**મજૂરો ક્યાંથી આવ્યા?** મોટે ભાગે આસપાસના જિલ્લાઓમાંથી. **1911**માં મુંબઈના સુતરાઉ કાપડ ઉદ્યોગના અડધા મજૂરો પાસેના **રત્નાગિરિ** જિલ્લામાંથી હતા; કાનપુરની મિલોને મોટા ભાગના મજૂરો કાનપુર જિલ્લાનાં ગામડાંમાંથી મળતા. "
  "નોકરી મેળવવી મુશ્કેલ હતી; ઉદ્યોગપતિઓ નવા મજૂરોની ભરતી માટે **જૉબર** રાખતા, જે મોટે ભાગે જૂનો અને વિશ્વાસુ મજૂર હતો; તે પોતાના ગામમાંથી લોકો લાવતો, તેમને વસાવવામાં મદદ કરતો અને મુશ્કેલીમાં પૈસા આપતો. સમય જતાં જૉબરો પૈસા અને ભેટ માગવા લાગ્યા અને મજૂરોના જીવન પર નિયંત્રણ રાખવા લાગ્યા. "
  "કારખાના મજૂરોની સંખ્યા **1901માં 5,84,000**થી વધીને **1946 સુધીમાં 24,36,000**થી વધુ થઈ."),
 "s5.growth.title": ("औद्योगिक विकास की विशेषताएँ", "ઔદ્યોગિક વિકાસની વિશેષતાઓ"),
 "s5.growth.body": (
  "- यूरोपीय प्रबंधकीय एजेंसियों ने **चाय और कॉफ़ी बाग़ानों, खनन, नील और जूट** में पैसा लगाया, जो ज़्यादातर निर्यात के लिए था, भारत में बिक्री के लिए नहीं।\n"
  "- भारतीय व्यवसायियों ने मैनचेस्टर के माल से प्रतिस्पर्धा से बचना चाहा। चूँकि धागा ब्रिटिश आयात का महत्त्वपूर्ण हिस्सा नहीं था, इसलिए आरंभिक भारतीय सूती मिलें कपड़े के बजाय **मोटा सूती धागा** बनाती थीं, और उसका बड़ा हिस्सा **चीन को निर्यात** होता था।\n"
  "- 20वीं सदी के पहले दशक में **स्वदेशी आंदोलन** ने विदेशी कपड़े का बहिष्कार किया, और औद्योगिक समूहों ने संरक्षण शुल्क की माँग की। **1906** से चीन में चीनी और जापानी मिलों का माल भर जाने से भारतीय धागे का निर्यात घटा, इसलिए भारतीय उद्योगपति धागे से **कपड़ा** बनाने की ओर मुड़े। **1900 से 1912 के बीच** भारत में सूती कपड़े का उत्पादन **दोगुना** हो गया।\n"
  "- **प्रथम विश्व युद्ध** ने एक बिलकुल नई स्थिति पैदा की। ब्रिटिश मिलें सेना की ज़रूरतें पूरी करने में व्यस्त हो गईं, इसलिए भारत में मैनचेस्टर का आयात घटा। भारतीय मिलों को अचानक एक विशाल घरेलू बाज़ार मिल गया और वे युद्ध की ज़रूरतें भी पूरी करने लगीं: **जूट के बोरे, सैनिकों की वर्दी का कपड़ा, तंबू, चमड़े के जूते, घोड़े और ख़च्चर की ज़ीन**। युद्ध के बाद **मैनचेस्टर भारतीय बाज़ार में अपनी पुरानी स्थिति कभी नहीं पा सका**।\n\n"
  "**लघु उद्योगों की प्रधानता:** बड़े कारख़ाने उद्योग का छोटा हिस्सा थे; अधिकांश उत्पादन छोटी कार्यशालाओं और घरों में होता था। 20वीं सदी में हथकरघा उत्पादन वास्तव में **बढ़ा**, जिसमें **फ़्लाई शटल** जैसी तकनीक ने मदद की; यह रस्सियों और पुलियों से चलने वाला यांत्रिक उपकरण है जो बाने के धागे को ताने में डालता है, जिससे प्रति मज़दूर उत्पादकता बढ़ती है। "
  "**1941** तक भारत के **35 प्रतिशत** से अधिक करघों में फ़्लाई शटल लगे थे (त्रावणकोर, मद्रास, मैसूर, कोचीन और बंगाल में 70–80 प्रतिशत)। फ़सल ख़राब होने पर मोटा कपड़ा बुनने वालों को नुक़सान होता था; महीन कपड़ा बुनने वालों की माँग संपन्न वर्ग से स्थिर रहती थी। महिलाओं और बच्चों सहित पूरे परिवार लंबे समय तक काम करते थे।",
  "- યુરોપીય મૅનેજિંગ એજન્સીઓએ **ચા અને કૉફીના બગીચા, ખાણકામ, ગળી અને શણ**માં મૂડી રોકી, જે મોટે ભાગે નિકાસ માટે હતું, ભારતમાં વેચાણ માટે નહિ.\n"
  "- ભારતીય વેપારીઓએ માન્ચેસ્ટરના માલ સાથે સ્પર્ધા ટાળવાનું પસંદ કર્યું. સૂતર બ્રિટિશ આયાતનો મહત્ત્વનો ભાગ ન હોવાથી શરૂઆતની ભારતીય સુતરાઉ મિલો કાપડને બદલે **જાડું સુતરાઉ સૂતર** બનાવતી, અને તેનો મોટો ભાગ **ચીનમાં નિકાસ** થતો.\n"
  "- 20મી સદીના પહેલા દાયકામાં **સ્વદેશી આંદોલને** વિદેશી કાપડનો બહિષ્કાર કર્યો, અને ઔદ્યોગિક જૂથોએ રક્ષણાત્મક જકાતની માગણી કરી. **1906**થી ચીનમાં ચીની અને જાપાની મિલોનો માલ ભરાઈ જતાં ભારતીય સૂતરની નિકાસ ઘટી, તેથી ભારતીય ઉદ્યોગપતિઓ સૂતરમાંથી **કાપડ** બનાવવા તરફ વળ્યા. **1900થી 1912 વચ્ચે** ભારતમાં સુતરાઉ કાપડનું ઉત્પાદન **બમણું** થયું.\n"
  "- **પ્રથમ વિશ્વયુદ્ધે** બિલકુલ નવી પરિસ્થિતિ ઊભી કરી. બ્રિટિશ મિલો લશ્કરની જરૂરિયાતો પૂરી કરવામાં વ્યસ્ત થઈ, તેથી ભારતમાં માન્ચેસ્ટરની આયાત ઘટી. ભારતીય મિલોને અચાનક વિશાળ ઘરેલુ બજાર મળ્યું અને તે યુદ્ધની જરૂરિયાતો પણ પૂરી કરવા લાગી: **શણની કોથળીઓ, લશ્કરી ગણવેશનું કાપડ, તંબૂ, ચામડાના બૂટ, ઘોડા અને ખચ્ચરનાં જીન**. યુદ્ધ પછી **માન્ચેસ્ટર ભારતીય બજારમાં પોતાનું જૂનું સ્થાન ક્યારેય પાછું ન મેળવી શક્યું**.\n\n"
  "**નાના ઉદ્યોગોનું પ્રભુત્વ:** મોટાં કારખાનાં ઉદ્યોગનો નાનો ભાગ હતાં; મોટા ભાગનું ઉત્પાદન નાની કાર્યશાળાઓ અને ઘરોમાં થતું. 20મી સદીમાં હાથશાળનું ઉત્પાદન ખરેખર **વધ્યું**, જેમાં **ફ્લાય શટલ** જેવી ટેકનોલોજીએ મદદ કરી; તે દોરડાં અને ગરગડીથી ચાલતું યાંત્રિક સાધન છે જે વાણાના દોરાને તાણામાં નાખે છે, જેથી મજૂરદીઠ ઉત્પાદકતા વધે છે. "
  "**1941** સુધીમાં ભારતની **35 ટકા**થી વધુ શાળોમાં ફ્લાય શટલ લાગ્યાં હતાં (ત્રાવણકોર, મદ્રાસ, મૈસૂર, કોચીન અને બંગાળમાં 70–80 ટકા). પાક નિષ્ફળ જાય ત્યારે જાડું કાપડ વણનારાઓને નુકસાન થતું; બારીક કાપડ વણનારાઓની માગ સંપન્ન વર્ગ તરફથી સ્થિર રહેતી. સ્ત્રીઓ અને બાળકો સહિત આખાં કુટુંબો લાંબા કલાકો કામ કરતાં."),
 "s5.market.title": ("माल के लिए बाज़ार: विज्ञापन", "માલ માટે બજાર: જાહેરાતો"),
 "s5.market.body": (
  "नए उपभोक्ता बनाने पड़े। **विज्ञापनों** ने उत्पादों को आकर्षक और ज़रूरी बना दिया।\n\n- मैनचेस्टर के कपड़े के बंडलों पर **'मेड इन मैनचेस्टर'** का लेबल होता, जो गुणवत्ता का निशान था।\n"
  "- लेबलों पर कृष्ण या सरस्वती जैसे **भारतीय देवी-देवताओं** की तस्वीरें होतीं, ताकि उत्पाद जाना-पहचाना और दैवी स्वीकृति वाला लगे।\n- निर्माता अपने उत्पादों को लोकप्रिय बनाने के लिए **कैलेंडर** छापते थे; कैलेंडर साल भर चाय की दुकानों और घरों में टँगे रहते। महत्त्वपूर्ण व्यक्तियों, सम्राटों और नवाबों की तस्वीरें भी विज्ञापनों में होती थीं।\n"
  "- जब भारतीय निर्माताओं ने विज्ञापन दिए, तो राष्ट्रवादी संदेश साफ़ था: **'भारतीय बनो, भारतीय ख़रीदो'** (स्वदेशी)। राष्ट्र की चिंता का अर्थ था भारतीयों द्वारा बनाए उत्पाद ख़रीदना।",
  "નવા ગ્રાહકો ઊભા કરવા પડ્યા. **જાહેરાતોએ** ઉત્પાદનોને આકર્ષક અને જરૂરી બનાવ્યાં.\n\n- માન્ચેસ્ટરના કાપડનાં બંડલ પર **'મેડ ઇન માન્ચેસ્ટર'**નું લેબલ રહેતું, જે ગુણવત્તાની નિશાની હતું.\n"
  "- લેબલ પર કૃષ્ણ કે સરસ્વતી જેવાં **ભારતીય દેવ-દેવીઓ**નાં ચિત્રો રહેતાં, જેથી ઉત્પાદન જાણીતું અને દૈવી માન્યતાવાળું લાગે.\n- ઉત્પાદકો પોતાનાં ઉત્પાદનો લોકપ્રિય બનાવવા **કૅલેન્ડર** છાપતા; કૅલેન્ડર આખું વર્ષ ચાની દુકાનો અને ઘરોમાં લટકતાં. મહત્ત્વની વ્યક્તિઓ, સમ્રાટો અને નવાબોનાં ચિત્રો પણ જાહેરાતોમાં રહેતાં.\n"
  "- ભારતીય ઉત્પાદકોએ જાહેરાતો આપી ત્યારે રાષ્ટ્રવાદી સંદેશ સ્પષ્ટ હતો: **'ભારતીય બનો, ભારતીય ખરીદો'** (સ્વદેશી). રાષ્ટ્રની ચિંતાનો અર્થ હતો ભારતીયોએ બનાવેલાં ઉત્પાદનો ખરીદવાં."),
 "s5.timeline.title": ("अध्याय की समयरेखा", "પ્રકરણની સમયરેખા"),
 "s5.timeline.body": (
  "| वर्ष | घटना |\n|---|---|\n| 1730 का दशक | इंग्लैंड में सबसे पहले कारख़ाने |\n| 1760 → 1787 | ब्रिटेन का कच्चे कपास का आयात 25 लाख से 2.2 करोड़ पाउंड |\n"
  "| 1764 | जेम्स हारग्रीव्ज़ की स्पिनिंग जेनी |\n| 1781 | जेम्स वॉट ने अपने सुधरे भाप इंजन का पेटेंट कराया |\n| 1772 | हेनरी पतुलो का दावा कि भारतीय वस्त्रों की माँग कभी कम नहीं होगी |\n"
  "| 1811–12 → 1850–51 | भारत के निर्यात में सूती कपड़ा 33% से 3% |\n| 1854 | बंबई की पहली सूती मिल (उत्पादन 1856 से) |\n| 1855 | बंगाल की पहली जूट मिल |\n"
  "| 1860 का दशक | अमेरिकी गृहयुद्ध: भारत से कच्चे कपास का निर्यात बढ़ा; कानपुर में एल्गिन मिल |\n| 1861 | अहमदाबाद की पहली सूती मिल |\n| 1874 | मद्रास की पहली कताई और बुनाई मिल |\n"
  "| 1917 | सेठ हुकुमचंद ने कलकत्ता में पहली भारतीय जूट मिल लगाई |\n| 1914–18 | प्रथम विश्व युद्ध: भारतीय उद्योगों का विस्तार |",
  "| વર્ષ | ઘટના |\n|---|---|\n| 1730નો દાયકો | ઇંગ્લૅન્ડમાં સૌથી પહેલાં કારખાનાં |\n| 1760 → 1787 | બ્રિટનની કાચા કપાસની આયાત 25 લાખથી 2.2 કરોડ પાઉન્ડ |\n"
  "| 1764 | જેમ્સ હારગ્રીવ્ઝની સ્પિનિંગ જેની |\n| 1781 | જેમ્સ વૉટે પોતાના સુધારેલા વરાળયંત્રની પેટન્ટ મેળવી |\n| 1772 | હેન્રી પટુલોનો દાવો કે ભારતીય કાપડની માગ ક્યારેય નહિ ઘટે |\n"
  "| 1811–12 → 1850–51 | ભારતની નિકાસમાં સુતરાઉ કાપડ 33%થી 3% |\n| 1854 | મુંબઈની પહેલી સુતરાઉ મિલ (ઉત્પાદન 1856થી) |\n| 1855 | બંગાળની પહેલી શણ મિલ |\n"
  "| 1860નો દાયકો | અમેરિકન આંતરવિગ્રહ: ભારતમાંથી કાચા કપાસની નિકાસ વધી; કાનપુરમાં એલ્ગિન મિલ |\n| 1861 | અમદાવાદની પહેલી સુતરાઉ મિલ |\n| 1874 | મદ્રાસની પહેલી કાંતણ અને વણાટ મિલ |\n"
  "| 1917 | શેઠ હુકમચંદે કલકત્તામાં પહેલી ભારતીય શણ મિલ સ્થાપી |\n| 1914–18 | પ્રથમ વિશ્વયુદ્ધ: ભારતીય ઉદ્યોગોનું વિસ્તરણ |"),

 "s6.memory.title": ("याद रखने की तरकीबें", "યાદ રાખવાની યુક્તિઓ"),
 "s6.memory.body": (
  "- **आदि = पहले:** सौदागर + गाँव + कारख़ाने नहीं।\n- **हाथ का श्रम क्यों? \"स-मौ-वि-प\":** **स**स्ता श्रम, **मौ**समी माँग, **वि**विध डिज़ाइन, अमीरों की **प**संद।\n"
  "- **कंपनी का नियंत्रण = \"गु-पे\":** **गु**माश्ता + **पे**शगी।\n- **भारतीय निर्यात 33% → 3%; मैनचेस्टर का आयात 0 → 31% → 50%।**\n- **पहली मिलें: बंबई 1854, बंगाल जूट 1855, अहमदाबाद 1861, मद्रास 1874।**",
  "- **આદિ = પહેલાં:** વેપારીઓ + ગામડાં + કારખાનાં નહિ.\n- **હાથનો શ્રમ કેમ? \"સ-ઋ-વિ-પ\":** **સ**સ્તો શ્રમ, **ઋ**તુગત માગ, **વિ**વિધ ડિઝાઇન, ધનિકોની **પ**સંદ.\n"
  "- **કંપનીનું નિયંત્રણ = \"ગુ-પે\":** **ગુ**માસ્તા + **પે**શગી.\n- **ભારતીય નિકાસ 33% → 3%; માન્ચેસ્ટરની આયાત 0 → 31% → 50%.**\n- **પહેલી મિલો: મુંબઈ 1854, બંગાળ શણ 1855, અમદાવાદ 1861, મદ્રાસ 1874.**"),
 "s6.mistakes.title": ("सामान्य गलतियाँ", "સામાન્ય ભૂલો"),
 "s6.mistakes.body": (
  "1. यह सोचना कि ब्रिटेन में मशीनों ने हाथ के श्रम की जगह जल्दी ले ली: बदलाव धीमा था; 19वीं सदी के अंत तक 20% से कम लोग उन्नत क्षेत्रों में काम करते थे।\n2. आर्कराइट (सूती मिल), हारग्रीव्ज़ (स्पिनिंग जेनी) और वॉट (भाप इंजन) को मिला देना।\n"
  "3. लिखना कि अमेरिकी गृहयुद्ध से भारत का कपास निर्यात घटा: यह **बढ़ा**।\n4. गुमाश्ता को बुनकर कहना: वह कंपनी का वेतनभोगी कर्मचारी था।\n5. कहना कि आरंभिक भारतीय मिलें भारत के लिए महीन कपड़ा बनाती थीं: वे **मोटा धागा** बनाती थीं, जिसका बड़ा हिस्सा चीन जाता था।\n"
  "6. याद रखें: 2025-26 में यह अध्याय केवल आवधिक मूल्यांकन के लिए है, बोर्ड पेपर के लिए नहीं।",
  "1. એમ માનવું કે બ્રિટનમાં યંત્રોએ હાથના શ્રમનું સ્થાન ઝડપથી લીધું: ફેરફાર ધીમો હતો; 19મી સદીના અંત સુધી 20%થી ઓછા લોકો આગળ વધેલાં ક્ષેત્રોમાં કામ કરતા.\n2. આર્કરાઇટ (સુતરાઉ મિલ), હારગ્રીવ્ઝ (સ્પિનિંગ જેની) અને વૉટ (વરાળયંત્ર)ને ભેળવી દેવા.\n"
  "3. લખવું કે અમેરિકન આંતરવિગ્રહથી ભારતની કપાસની નિકાસ ઘટી: તે **વધી**.\n4. ગુમાસ્તાને વણકર કહેવો: તે કંપનીનો પગારદાર નોકર હતો.\n5. કહેવું કે શરૂઆતની ભારતીય મિલો ભારત માટે બારીક કાપડ બનાવતી: તે **જાડું સૂતર** બનાવતી, જેનો મોટો ભાગ ચીન જતો.\n"
  "6. યાદ રાખો: 2025-26માં આ પ્રકરણ ફક્ત સામયિક મૂલ્યાંકન માટે છે, બોર્ડ પેપર માટે નહિ."),
 "s6.tip.title": ("कक्षा में करके देखिए", "વર્ગમાં કરી જુઓ"),
 "s6.tip.body": ("पुराने उत्पाद लेबल, कैलेंडर चित्र और विज्ञापन (या उनकी तस्वीरें) इकट्ठा कीजिए। विद्यार्थी उनमें प्रयुक्त तरीक़े पहचानें: देवी-देवता, प्रसिद्ध व्यक्ति, 'मेड इन मैनचेस्टर', 'भारतीय बनो, भारतीय ख़रीदो'। फिर हर समूह 1920 के दशक की किसी भारतीय मिल के उत्पाद का विज्ञापन बनाए।",
                 "જૂનાં ઉત્પાદન લેબલ, કૅલેન્ડર ચિત્રો અને જાહેરાતો (કે તેમની છબીઓ) એકઠાં કરો. વિદ્યાર્થીઓ તેમાં વપરાયેલી યુક્તિઓ ઓળખે: દેવ-દેવીઓ, પ્રખ્યાત વ્યક્તિઓ, 'મેડ ઇન માન્ચેસ્ટર', 'ભારતીય બનો, ભારતીય ખરીદો'. પછી દરેક જૂથ 1920ના દાયકાની કોઈ ભારતીય મિલના ઉત્પાદનની જાહેરાત બનાવે."),
 "s6.reflection.title": ("सोचिए और समझाइए", "વિચારો અને સમજાવો"),
 "s6.reflection.body": ("यदि आप भरपूर सस्ते मज़दूरों वाले विक्टोरिया-कालीन उद्योगपति होते, तो क्या महँगी मशीनें ख़रीदते? अपने उत्तर के दो कारण दीजिए।", "જો તમે પુષ્કળ સસ્તા મજૂરોવાળા વિક્ટોરિયા યુગના ઉદ્યોગપતિ હોત, તો શું મોંઘાં યંત્રો ખરીદત? તમારા જવાબનાં બે કારણો આપો."),
 "s6.connection.title": ("यह कहाँ ले जाता है", "આ ક્યાં લઈ જાય છે"),
 "s6.connection.body": (
  "- **अध्याय 2, भारत में राष्ट्रवाद:** स्वदेशी आंदोलन और विदेशी कपड़े के बहिष्कार ने भारतीय मिलों की मदद की।\n- **भूगोल, विनिर्माण उद्योग:** आज के सूती वस्त्र, जूट और लोहा-इस्पात उद्योग।\n"
  "- **अर्थशास्त्र, भारतीय अर्थव्यवस्था के क्षेत्रक:** संगठित और असंगठित क्षेत्रक, जैसे कारख़ाने और घरेलू इकाइयाँ।",
  "- **પ્રકરણ 2, ભારતમાં રાષ્ટ્રવાદ:** સ્વદેશી આંદોલન અને વિદેશી કાપડના બહિષ્કારે ભારતીય મિલોને મદદ કરી.\n- **ભૂગોળ, ઉત્પાદન ઉદ્યોગો:** આજના સુતરાઉ કાપડ, શણ અને લોખંડ-સ્ટીલ ઉદ્યોગો.\n"
  "- **અર્થશાસ્ત્ર, ભારતીય અર્થતંત્રનાં ક્ષેત્રો:** સંગઠિત અને અસંગઠિત ક્ષેત્રો, જેમ કે કારખાનાં અને ઘરગથ્થુ એકમો."),
 "s6.mastery.title": ("निपुणता चुनौती", "નિપુણતા પડકાર"),
 "s6.mastery.body": (
  "लगभग 100 शब्दों में समझाइए कि ईस्ट इंडिया कंपनी की नीतियों ने भारतीय बुनकरों को कैसे प्रभावित किया।\n\n"
  "**आदर्श उत्तर:** कंपनी ने मौजूदा व्यापारियों और दलालों को हटाया और बुनकरों की निगरानी, कपड़ा इकट्ठा करने और गुणवत्ता जाँचने के लिए गुमाश्ते नियुक्त किए। पेशगी की व्यवस्था में बुनकर कच्चे माल के लिए क़र्ज़ लेते और अपना कपड़ा केवल गुमाश्ता को बेच सकते थे, इसलिए उनकी मोलभाव और दूसरों को बेचने की आज़ादी ख़त्म हो गई और उन्हें बहुत कम क़ीमत मिलती थी। "
  "गुमाश्ते बाहरी लोग थे जो देरी पर बुनकरों को सज़ा देते थे। कई बुनकरों ने गाँव छोड़े, विद्रोह किया या मज़दूर बन गए। बाद में मैनचेस्टर के आयात ने उनके बाज़ार ख़त्म कर दिए, और अमेरिकी गृहयुद्ध ने कच्चे कपास को दुर्लभ और महँगा बना दिया।",
  "આશરે 100 શબ્દોમાં સમજાવો કે ઈસ્ટ ઇન્ડિયા કંપનીની નીતિઓએ ભારતીય વણકરોને કેવી રીતે અસર કરી.\n\n"
  "**આદર્શ જવાબ:** કંપનીએ હાલના વેપારીઓ અને દલાલોને દૂર કર્યા અને વણકરોની દેખરેખ, કાપડ એકઠું કરવા અને ગુણવત્તા તપાસવા ગુમાસ્તા નીમ્યા. પેશગીની વ્યવસ્થામાં વણકરો કાચા માલ માટે લોન લેતા અને પોતાનું કાપડ ફક્ત ગુમાસ્તાને જ વેચી શકતા, તેથી તેમની ભાવતાલ અને બીજાને વેચવાની સ્વતંત્રતા ખતમ થઈ અને તેમને ખૂબ ઓછો ભાવ મળતો. "
  "ગુમાસ્તા બહારના લોકો હતા જે મોડું થાય તો વણકરોને સજા કરતા. ઘણા વણકરોએ ગામ છોડ્યાં, બળવો કર્યો કે મજૂર બન્યા. પછીથી માન્ચેસ્ટરની આયાતે તેમનાં બજાર ખતમ કર્યાં, અને અમેરિકન આંતરવિગ્રહે કાચા કપાસને દુર્લભ અને મોંઘો બનાવ્યો."),
 "s6.summary.title": ("अध्याय सारांश", "પ્રકરણ સારાંશ"),
 "s6.summary.body": (
  "- आदि-औद्योगीकरण: कारख़ानों से पहले सौदागरों ने अंतरराष्ट्रीय बाज़ारों के लिए ग्रामीण उत्पादकों को पैसा दिया।\n- कारख़ाने 1730 के दशक से बने; पहले कपास और फिर लोहा-इस्पात आगे रहे; पर बदलाव धीमा था और अधिकांश मज़दूर कारीगर और श्रमिक ही रहे।\n"
  "- सस्ते श्रम, मौसमी माँग, विविधता और अमीरों की पसंद के कारण कई उद्योगपति हाथ का श्रम पसंद करते थे; मज़दूर बेरोज़गारी झेलते थे और स्पिनिंग जेनी जैसी मशीनों से डरते थे।\n"
  "- महीन वस्त्र-व्यापार में भारत का दबदबा था; कंपनी के गुमाश्तों और पेशगी, मैनचेस्टर के आयात और 1860 के दशक में कपास की कमी ने कई बुनकरों को बर्बाद कर दिया।\n"
  "- भारतीय कारख़ाने (1854 से बंबई में) चीन व्यापार से धनी हुए व्यापारियों ने लगाए; मज़दूर जॉबरों के ज़रिए आए; स्वदेशी आंदोलन और प्रथम विश्व युद्ध ने भारतीय उद्योग की मदद की; लघु और हथकरघा उत्पादन की प्रधानता बनी रही।\n- विज्ञापनों ने बाज़ार बनाए: लेबलों पर देवता, कैलेंडर, और 'भारतीय बनो, भारतीय ख़रीदो'।",
  "- આદિ-ઔદ્યોગિકીકરણ: કારખાનાં પહેલાં વેપારીઓએ આંતરરાષ્ટ્રીય બજારો માટે ગ્રામીણ ઉત્પાદકોને નાણાં આપ્યાં.\n- કારખાનાં 1730ના દાયકાથી બન્યાં; પહેલાં કપાસ અને પછી લોખંડ-સ્ટીલ મોખરે રહ્યાં; પણ ફેરફાર ધીમો હતો અને મોટા ભાગના મજૂરો કારીગરો અને શ્રમિકો જ રહ્યા.\n"
  "- સસ્તો શ્રમ, ઋતુગત માગ, વિવિધતા અને ધનિકોની પસંદને કારણે ઘણા ઉદ્યોગપતિઓ હાથના શ્રમને પસંદ કરતા; મજૂરો બેરોજગારી ભોગવતા અને સ્પિનિંગ જેની જેવાં યંત્રોથી ડરતા.\n"
  "- બારીક કાપડના વેપારમાં ભારતનું વર્ચસ્વ હતું; કંપનીના ગુમાસ્તા અને પેશગી, માન્ચેસ્ટરની આયાત અને 1860ના દાયકામાં કપાસની અછતે ઘણા વણકરોને બરબાદ કર્યા.\n"
  "- ભારતીય કારખાનાં (1854થી મુંબઈમાં) ચીનના વેપારથી ધનિક બનેલા વેપારીઓએ સ્થાપ્યાં; મજૂરો જૉબરો મારફતે આવ્યા; સ્વદેશી આંદોલન અને પ્રથમ વિશ્વયુદ્ધે ભારતીય ઉદ્યોગને મદદ કરી; નાના અને હાથશાળ ઉત્પાદનનું પ્રભુત્વ રહ્યું.\n- જાહેરાતોએ બજારો ઊભાં કર્યાં: લેબલ પર દેવો, કૅલેન્ડર, અને 'ભારતીય બનો, ભારતીય ખરીદો'."),
 "s6.examtips.title": ("परीक्षा के सुझाव", "પરીક્ષા માટે સૂચનો"),
 "s6.examtips.body": (
  "- 2025-26 में इस अध्याय का मूल्यांकन केवल **आवधिक परीक्षाओं** में होता है, बोर्ड पेपर में नहीं।\n- सामान्य प्रश्न: आदि-औद्योगीकरण, हाथ के श्रम को प्राथमिकता क्यों, गुमाश्ते और पेशगी की व्यवस्था, प्रथम विश्व युद्ध के प्रभाव, विज्ञापनों की भूमिका।\n"
  "- आँकड़ों का प्रयोग कीजिए: 33% → 3%, 31% → 50%, 321 भाप इंजन, 1854 की बंबई मिल।",
  "- 2025-26માં આ પ્રકરણનું મૂલ્યાંકન ફક્ત **સામયિક કસોટીઓ**માં થાય છે, બોર્ડ પેપરમાં નહિ.\n- સામાન્ય પ્રશ્નો: આદિ-ઔદ્યોગિકીકરણ, હાથના શ્રમને પસંદગી કેમ, ગુમાસ્તા અને પેશગીની વ્યવસ્થા, પ્રથમ વિશ્વયુદ્ધની અસરો, જાહેરાતોની ભૂમિકા.\n"
  "- આંકડાઓનો ઉપયોગ કરો: 33% → 3%, 31% → 50%, 321 વરાળયંત્રો, 1854ની મુંબઈ મિલ."),
 "s6.flash1.front": ("आदि-औद्योगीकरण क्या है?", "આદિ-ઔદ્યોગિકીકરણ એટલે શું?"),
 "s6.flash1.back": ("कारख़ानों से पहले, सौदागरों की पूँजी से गाँवों में अंतरराष्ट्रीय बाज़ारों के लिए बड़े पैमाने पर उत्पादन।", "કારખાનાં પહેલાં, વેપારીઓની મૂડીથી ગામડાંમાં આંતરરાષ્ટ્રીય બજારો માટે મોટા પાયે ઉત્પાદન."),
 "s6.flash2.front": ("पेशगी की व्यवस्था क्या थी?", "પેશગીની વ્યવસ્થા શું હતી?"),
 "s6.flash2.back": ("कच्चे माल के लिए बुनकरों को कंपनी का क़र्ज़; फिर कपड़ा गुमाश्ता को सौंपना पड़ता था।", "કાચા માલ માટે વણકરોને કંપનીની લોન; પછી કાપડ ગુમાસ્તાને સોંપવું પડતું."),
 "s6.flash3.front": ("फ़्लाई शटल क्या था?", "ફ્લાય શટલ શું હતું?"),
 "s6.flash3.back": ("रस्सियों और पुलियों से चलने वाला उपकरण जो बाने को ताने में डालता है, जिससे बुनकर की उत्पादकता बढ़ती है।", "દોરડાં અને ગરગડીથી ચાલતું સાધન જે વાણાને તાણામાં નાખે છે, જેથી વણકરની ઉત્પાદકતા વધે છે."),
 "s6.flash4.front": ("भारत की पहली सूती मिल कब और कहाँ बनी?", "ભારતની પહેલી સુતરાઉ મિલ ક્યારે અને ક્યાં બની?"),
 "s6.flash4.back": ("बंबई, 1854 (उत्पादन 1856 से)।", "મુંબઈ, 1854 (ઉત્પાદન 1856થી)."),
}
